### JS Script Module
- Runs in the browser environment (executed on the frontend)
- Supports all standard JavaScript syntax and built-in objects (String, Array, Object, Math, Date, JSON, etc.)
- Does not support asynchronous operations (async/await) or DOM manipulation
- Does not support Node.js modules (such as fs, path, etc.)
- Must define a main(vars) function as the entry point
- The vars parameter supports read and write operations; changes are automatically synced back to the workflow
- The return value of the main function is stored in the specified result variable

### Common Uses
1. Data processing: string processing, array operations, object conversion
2. Math calculation: complex computations, statistical analysis
3. Logic evaluation: conditional checks, data validation
4. Data conversion: JSON parsing, format conversion
5. Variable operations: read, modify, and compute workflow variables

### Code Examples
```javascript
// Example 1: String processing
function main(vars) {
  const text = vars.inputText || "";
  const processed = text.trim().toUpperCase();
  vars.outputText = processed;
  return processed.length;
}

// Example 2: Array operations
function main(vars) {
  const numbers = vars.numberList || [];
  const sum = numbers.reduce((a, b) => a + b, 0);
  const avg = sum / numbers.length;
  vars.average = avg;
  return { sum, avg };
}

// Example 3: JSON processing
function main(vars) {
  const jsonStr = vars.jsonData || "{}";
  const data = JSON.parse(jsonStr);
  data.timestamp = Date.now();
  vars.processedData = data;
  return JSON.stringify(data);
}

// Example 4: Conditional evaluation
function main(vars) {
  const score = vars.score || 0;
  let grade = "F";
  if (score >= 90) grade = "A";
  else if (score >= 80) grade = "B";
  else if (score >= 70) grade = "C";
  else if (score >= 60) grade = "D";
  vars.grade = grade;
  return grade;
}
